"use strict";
// Exercise the actual app handlers with controllable asynchronous media events.
// No audio, labels, model inference or rendering is generated by this check.
const assert = require("node:assert/strict");
const fs = require("node:fs"), path = require("node:path"), vm = require("node:vm");
const S = require("../../workbench-web/workbench-state.js");
const source = fs.readFileSync(process.argv[2] || path.resolve(__dirname, "../../workbench-web/app.js"), "utf8");
const checks = [];
function test(name, fn) {
  try { fn(); checks.push({name, passed:true}); }
  catch (e) { checks.push({name, passed:false, error:e.message}); }
}
function functionSource(name) {
  const start = source.indexOf("  function " + name + "(");
  assert.ok(start >= 0, name);
  const end = source.indexOf("\n  function ", start + 1);
  return source.slice(start, end);
}
function harness(offset=0, duration=1) {
  function media(src, length) {
    const events = {}; let position=0;
    return {src, duration:length, readyState:1, paused:true, hidden:false, seeking:false,
      get currentTime() {return position;},
      set currentTime(v) {position=Math.max(0,Math.min(length,v)); this.seeking=true;},
      get ended() {return position>=length;},
      pause() {this.paused=true; this.emit("pause");},
      play() {this.paused=false; this.emit("play"); return Promise.resolve();},
      addEventListener(event, handler) {(events[event] ||= []).push(handler);},
      emit(event) {for (const fn of events[event] || []) fn();},
      settle() {
        const requested=this.seeking;this.seeking=false;this.emit("timeupdate");
        if(requested)this.emit("seeked");
      },
      finish() {position=length;this.seeking=false;this.paused=true;this.emit("timeupdate");this.emit("ended");}
    };
  }
  const elements = {audio:media("audio",30), video:media("clip",duration),
    "compare-video":media("reference",30), playhead:{}, clock:{},
    "loop-enabled":{checked:false}, "loop-a":{value:offset}, "loop-b":{value:offset+duration}};
  const state = {data:{project:{duration:30}},time:0,comparing:false,syncingMedia:false,
    selectedRender:{actual_start:offset,actual_end:offset+duration}, compare:{actual_start:0,actual_end:30},
    mediaSeeks:S.createMediaSeeks?.(),deferredVideoSeek:false};
  const context = {state, $:id=>elements[id], videoOffset:()=>offset, clock:String,
    drawTimeline:()=>{}, notice:()=>{}, updateComparison:()=>{}, Number, Math};
  vm.createContext(context);
  const events = source.slice(source.indexOf('  $("audio").addEventListener("timeupdate"'),
    source.indexOf('  window.addEventListener("pagehide"'));
  vm.runInContext(["renderBounds","comparisonRange","syncComparison","seek","enforceLoop"]
    .map(functionSource).join("\n") + "\n" + events, context);
  return {state, elements, seek:context.seek, sync:context.syncComparison};
}
test("short clip: explicit whole-song 2 seconds survives async boundary seeked",()=>{
  const h=harness(); h.seek(2); h.elements.video.settle();
  assert.equal(h.state.time,2); assert.equal(h.elements.playhead.value,"2.000");
  assert.equal(h.elements.audio.currentTime,2);
});
test("nonzero clip origin: seeking before the tail keeps the requested song time",()=>{
  const h=harness(27.6,.433); h.seek(2); h.elements.video.settle();
  assert.equal(h.state.time,2); assert.equal(h.elements.video.currentTime,0);
});
test("playing video stops outside its coverage instead of pulling the playhead back",()=>{
  const h=harness(); h.elements.video.play(); h.seek(3); h.elements.video.settle();
  assert.equal(h.state.time,3); assert.equal(h.elements.video.paused,true);
});
test("rapid programmatic seeks coalesce; later native video seeking still works",()=>{
  const h=harness(20,1); h.seek(20.2); h.seek(20.7); h.seek(5); h.elements.video.settle();
  assert.equal(h.state.time,5);
  h.elements.video.currentTime=.4; h.elements.video.settle();
  assert.equal(h.state.time,20.4);
});
test("native video seek can supersede a pending programmatic seek",()=>{
  const h=harness(20,1); h.seek(4);
  h.elements.video.currentTime=.8; h.elements.video.settle();
  assert.equal(h.state.time,20.8);
});
test("explicit song seek while loading survives loadedmetadata",()=>{
  const h=harness(20,1); h.elements.video.readyState=0; h.elements.video.duration=NaN;
  h.seek(5); h.elements.video.readyState=1; h.elements.video.duration=1;
  h.elements.video.emit("loadedmetadata"); h.elements.video.settle();
  assert.equal(h.state.time,5);
});
test("metadata loading does not rewind ongoing audio after an explicit song seek",()=>{
  const h=harness(20,1); h.elements.audio.play(); h.elements.video.readyState=0;
  h.seek(5); h.elements.audio.currentTime=5.5; h.elements.audio.settle();
  h.elements.video.readyState=1; h.elements.video.emit("loadedmetadata");
  assert.equal(h.state.time,5.5);
});
test("comparison alignment does not asynchronously replace the whole-song position",()=>{
  const h=harness(20,1); h.state.comparing=true; h.seek(5); h.elements.video.settle();
  assert.equal(h.state.time,5); assert.equal(h.elements["compare-video"].currentTime,20);
});
test("in-range playback and A/B loop retain their absolute song clock",()=>{
  const h=harness(20,1); h.seek(20.2); h.elements.video.settle();
  h.elements.video.play(); h.elements.video.currentTime=.4; h.elements.video.settle();
  assert.equal(h.state.time,20.4);
  h.elements["loop-enabled"].checked=true; h.elements["loop-a"].value=20.1;
  h.elements["loop-b"].value=20.8; h.elements.video.currentTime=.9;
  h.elements.video.emit("timeupdate"); h.elements.video.settle();
  assert.equal(h.state.time,20.1);
});
test("ended loop and whole-song bounds stay valid",()=>{
  const h=harness(); h.elements["loop-enabled"].checked=true; h.elements["loop-b"].value=1;
  h.elements.video.finish(); h.elements.video.settle(); assert.equal(h.state.time,0);
  h.elements["loop-enabled"].checked=false; h.seek(-8); h.elements.video.settle();
  assert.equal(h.state.time,0); h.seek(99); h.elements.video.settle(); assert.equal(h.state.time,30);
});
test("no-op, coalesced, changed-source and native seek acknowledgements",()=>{
  const sync=S.createMediaSeeks(); let writes=0, pos=0;
  const media={src:"one",duration:10,seeking:false,get currentTime(){return pos;},
    set currentTime(value){writes++;pos=value;this.seeking=true;}};
  sync.set(media,0); assert.equal(writes,0); assert.equal(sync.consume(media),false);
  sync.set(media,2); sync.set(media,3); assert.equal(writes,2);
  media.seeking=false; sync.set(media,3); assert.equal(writes,2);
  assert.equal(sync.consume(media),true); assert.equal(sync.consume(media),false);
  sync.set(media,4); media.src="two"; assert.equal(sync.consume(media),false);
  sync.set(media,5); media.currentTime=6; assert.equal(sync.consume(media),false);
  sync.set(media,7); sync.clear(media); assert.equal(sync.consume(media),false);
});
test("paused native audio seek updates the song clock without starting playback",()=>{
  const h=harness(); h.state.time=2; h.elements.audio.currentTime=12.5; h.elements.audio.settle();
  assert.equal(h.state.time,12.5); assert.equal(h.elements.audio.paused,true);
  assert.equal(h.elements.playhead.value,"12.500");
});
test("native seeking takes control from the other playing media in both directions",()=>{
  const h=harness(20,1); h.elements.video.play();
  h.elements.audio.currentTime=5; h.elements.audio.settle();
  assert.equal(h.state.time,5); assert.equal(h.elements.video.paused,true);
  h.elements.audio.play(); h.elements.video.currentTime=.5; h.elements.video.settle();
  assert.equal(h.state.time,20.5); assert.equal(h.elements.audio.paused,true);
});
test("programmatic audio alignment acknowledgement does not overwrite the requested time",()=>{
  const h=harness(); h.elements.audio.duration=2; h.seek(3); h.elements.audio.settle();
  assert.equal(h.state.time,3); assert.equal(h.elements.audio.currentTime,2);
});
test("natural audio end updates the final allowed song timestamp despite paused timeupdate",()=>{
  const h=harness(); h.state.data.project.duration=29.999375; h.state.time=29.8;
  h.elements.audio.finish(); assert.equal(h.state.time,29.999375);
  assert.equal(h.elements.playhead.value,"29.999");
});
test("natural video end includes the real clip offset",()=>{
  const h=harness(20,1); h.state.time=20.8; h.elements.video.finish();
  assert.equal(h.state.time,21); assert.equal(h.elements.video.paused,true);
});
test("audio end with valid A/B looping returns to A and continues playing",()=>{
  const h=harness(); h.elements["loop-enabled"].checked=true;
  h.elements["loop-a"].value=29; h.elements["loop-b"].value=30; h.elements.audio.finish();
  h.elements.audio.settle(); assert.equal(h.state.time,29); assert.equal(h.elements.audio.paused,false);
});
test("invalid end loop stops and still refreshes the final song position",()=>{
  const h=harness(); h.state.time=29.8; h.elements["loop-enabled"].checked=true;
  h.elements["loop-a"].value=31; h.elements["loop-b"].value=32; h.elements.audio.finish();
  assert.equal(h.state.time,30); assert.equal(h.elements["loop-enabled"].checked,false);
  assert.equal(h.elements.audio.paused,true);
});
test("late clip end cannot undo a new seek outside its range",()=>{
  const h=harness(); h.seek(5); h.elements.video.finish();
  assert.equal(h.state.time,5);
});
test("late audio end cannot take over from a playing video",()=>{
  const h=harness(20,1); h.state.time=20.5; h.elements.video.play(); h.elements.audio.finish();
  assert.equal(h.state.time,20.5); assert.equal(h.elements.video.paused,false);
});
console.log(JSON.stringify({suite:"media-seek",passed:checks.filter(x=>x.passed).length,
  total:checks.length,checks},null,2));
if(checks.some(x=>!x.passed))process.exitCode=1;
